// Shellfruit loop, replant step: once the replanted Blastberries are primed (one stage after
// placing), break them one at a time and pick up any Shellfruit straight away, so a later
// explosion can't destroy it. Then the plot goes back to growing Blastberries.
function onSession() {
  if (plot.step.id !== "main-3") return;
  const primed = plot.all("blastberry").filter((p) => p.primed);
  if (!primed.length) return;
  for (const b of primed) {
    b.break();
    for (const s of plot.all("shellfruit")) s.harvest();
  }
  plot.goto("main");
}

