//  Devourer: break roots, keep spawners only where needed, fill the rest
//  (Plot script, one Devourer layout step)
//
//  1. Roots: every session, before anything else, each Devourer root on
//     the plot is broken (whether or not the clearRoots policy is on).
//  2. Spawner ring: a Puffercloud or Zombud from the layout is only put
//     back while it's needed, that is while one of the Devourer spots it
//     touches is empty and waiting to spawn. Once every spot it touches has
//     a Devourer growing (or grown, waiting for harvest), a destroyed or
//     decayed one is not replaced. A Puffercloud or Zombud that is still
//     standing is left alone until it's gone.
//  3. Filler: every other cell (destroyed ring cells that aren't needed,
//     and the cells the layout leaves empty) gets Nether Wart on soul sand
//     and Cocoa Beans on farmland. Both are free, give the Devourers
//     Improved Harvest Boost / Immunity and stop other spawns.
//  4. When a Devourer is harvested its spot is empty again: the fillers in
//     its ring are swapped back to the Puffercloud/Zombud of the layout in
//     the same session, so the next Devourer can spawn there.
//  Like the hybrid Aloe regrow, this works by changing the plot's layout
//  (plot.setLayout); the built-in upkeep places what the layout asks for.
// =====================================================================

// ---- Settings ----
const BREAK_ROOTS = true;
const FILL_EMPTY_CELLS = true;     // cells the layout leaves empty get a filler too
const FILLER = { soul_sand: "nether_wart", farmland: "cocoa_beans" };
// Ground of cells the layout leaves empty (the layout doesn't say). Ring cells and
// spots take the ground their plant needs (Zombud soul sand, Puffercloud farmland).
const EMPTY_CELL_GROUND = "farmland";
// Let the engine skip "replace before decay" for ring inputs whose spots are all
// growing (the same rule as point 2, for inputs that are still standing).
const ENGINE_SKIPS_UNNEEDED = true;

const DEVOURER = "devourer";

// ---- Kept between cycles ----
let base = null;        // this step's own layout
let spots = [];         // Devourer spots: "r,c"
let ringOf = {};        // ring input cell "r,c" -> spots it counts for
let groundOf = {};      // "r,c" -> ground block
let appliedKey = null;
let tally = { rootsBroken: 0, swappedToInput: 0, fillersPlanted: 0 };

// ---- Small helpers ----
const key = (r, c) => `${r},${c}`;
const cellOf = (k) => k.split(",").map((x) => Number(x));
const inside = (r, c) => r >= 0 && r < 10 && c >= 0 && c < 10;

function ring(r, c, size) {
  const out = [];
  for (let dr = -1; dr <= size; dr++) for (let dc = -1; dc <= size; dc++) {
    const inner = dr >= 0 && dr < size && dc >= 0 && dc < size;
    if (!inner && inside(r + dr, c + dc)) out.push(key(r + dr, c + dc));
  }
  return out;
}

function footprint(row, col, size) {
  const out = [];
  for (let dr = 0; dr < size; dr++) for (let dc = 0; dc < size; dc++) out.push(key(row + dr, col + dc));
  return out;
}

// ---- Learning the layout ----
function capture() {
  base = plot.layout;
  appliedKey = null;
  const needs = (info(DEVOURER).requirements ?? []).map((q) => q.kind);
  spots = base.targets.filter((t) => t.mutation === DEVOURER).map((t) => key(t.row, t.col));
  ringOf = {};
  groundOf = {};
  for (const s of spots) {
    const [r, c] = cellOf(s);
    groundOf[s] = info(DEVOURER).ground;
    for (const k of ring(r, c, 1)) {
      const p = base.plants.find((e) => e.size === 1 && key(e.row, e.col) === k);
      if (!p || !needs.includes(p.kind)) continue;
      ringOf[k] = [...(ringOf[k] ?? []), s];
    }
  }
  for (const p of base.plants) for (const k of footprint(p.row, p.col, p.size)) groundOf[k] = info(p.kind).ground;
  for (const r of range(10)) for (const c of range(10)) {
    if (groundOf[key(r, c)] === undefined) groundOf[key(r, c)] = EMPTY_CELL_GROUND;
  }
}

// ---- Roots ----
function breakRoots() {
  for (const p of plot.plants.filter((q) => q.root)) {
    if (p.break()) tally.rootsBroken++;
  }
}

// ---- Which ring inputs are needed ----
function spotGrowing(s) {
  const [r, c] = cellOf(s);
  const p = plot.at(r, c);
  return !!p && !p.dead && p.kind === DEVOURER && p.row === r && p.col === c;
}

const needed = (k) => (ringOf[k] ?? []).some((s) => !spotGrowing(s));

function standing(k, kind) {
  const [r, c] = cellOf(k);
  const p = plot.at(r, c);
  return !!p && !p.dead && p.kind === kind && p.row === r && p.col === c;
}

// ---- Layout: targets as they are, ring inputs only where needed, filler elsewhere ----
function buildLayout() {
  const plants = [];
  const covered = {};
  for (const t of base.targets) for (const k of footprint(t.row, t.col, t.size ?? 1)) covered[k] = true;
  for (const p of base.plants) {
    const k = key(p.row, p.col);
    for (const f of footprint(p.row, p.col, p.size)) covered[f] = true;
    if (!ringOf[k] || needed(k) || standing(k, p.kind)) {
      plants.push({ kind: p.kind, row: p.row, col: p.col });
      continue;
    }
    const filler = FILLER[groundOf[k]];
    if (filler) plants.push({ kind: filler, row: p.row, col: p.col });
  }
  if (FILL_EMPTY_CELLS) {
    for (const r of range(10)) for (const c of range(10)) {
      const k = key(r, c);
      if (covered[k]) continue;
      const filler = FILLER[groundOf[k]];
      if (filler) plants.push({ kind: filler, row: r, col: c });
    }
  }
  return { plants, targets: base.targets.map((t) => ({ mutation: t.mutation, row: t.row, col: t.col })) };
}

function applyLayout() {
  const layout = buildLayout();
  const k = JSON.stringify(layout);
  if (k === appliedKey) return;
  const before = {};
  for (const p of plot.plants) before[key(p.row, p.col)] = p.kind;
  plot.setLayout(layout);
  appliedKey = k;
  for (const e of layout.plants) {
    const now = plot.at(e.row, e.col);
    if (!now || now.kind !== e.kind || before[key(e.row, e.col)] === e.kind) continue;
    now.waterIt(); // plants put down by a script start dry
    if (e.kind === FILLER.soul_sand || e.kind === FILLER.farmland) tally.fillersPlanted++;
    else if (ringOf[key(e.row, e.col)]) tally.swappedToInput++;
  }
}

