function onStart() {
  if (ENGINE_SKIPS_UNNEEDED) plot.setPolicy({ onlyReplaceForEmptyTargets: true });
  capture();
}

function onStepChange(e) {
  capture();
}

function onSession() {
  if (!base) capture();
  if (!spots.length) return;
  if (BREAK_ROOTS) breakRoots();
  applyLayout(); // the built-in upkeep then fills what the roots destroyed
}

