  applyLayout(); // spots harvested this session get their spawner back now
  metric("Devourer roots broken", tally.rootsBroken);
  metric("Ring cells put back for an empty spot", tally.swappedToInput);
  metric("Nether Wart / Cocoa Beans planted", tally.fillersPlanted);
  metric("Devourer spots growing", spots.filter((s) => spotGrowing(s)).length);
}

